{
  "findings": [
    {
      "ref": "[D512]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with their child via Google Classroom.",
      "stance": "risk",
      "quote": "Your kid will receive an email when the teacher posts an announcement. These emails come through your kid's email account, not in Classroom."
    },
    {
      "ref": "[D512]",
      "area": "contact",
      "claim": "A parent reports that the app does not have a built‑in chat feature that can be turned off by default.",
      "stance": "neutral",
      "quote": "Maybe. Teachers may assign collaborative projects, such as a group research paper in Google Docs or a group dialogue, where students comment on each other's work. But if the class isn't using the tools responsibly, a teacher or administrator can turn them all off."
    },
    {
      "ref": "[D512]",
      "area": "money",
      "claim": "A parent reports that the app does not push in‑app purchases, loot boxes, pay‑to‑win, or subscription traps.",
      "stance": "neutral",
      "quote": "Google Classroom is just one part of Google's Workspace for Education, and some of the apps, including third‑party programs, can be tracked."
    },
    {
      "ref": "[D512]",
      "area": "data",
      "claim": "A parent reports that the app may collect data when additional services like YouTube or Maps are enabled.",
      "stance": "risk",
      "quote": "if the school's administrator enables Additional Services, such as YouTube and Maps, Google may collect data on those apps as it would for any of its other consumer apps."
    },
    {
      "ref": "[D512]",
      "area": "data",
      "claim": "A parent reports that the app can share data with third parties who could profile and target the child.",
      "stance": "risk",
      "quote": "those third parties could collect information from your kid, then profile and target them using that data."
    },
    {
      "ref": "[D512]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice, as the app uses a school account that cannot be tracked beyond educational purposes.",
      "stance": "mitigation",
      "quote": "Logging in with a school account, rather than a personal Gmail account, protects kids from some data collection because education accounts can't be tracked or mined for data (beyond what's necessary for educational purposes)."
    },
    {
      "ref": "[D512]",
      "area": "content",
      "claim": "A parent reports that the app may expose children to mature YouTube content unless restricted mode is enabled by the administrator.",
      "stance": "risk",
      "quote": "If your kid has YouTube enabled in their Classroom account, you'll need to speak to the admin, not the teacher, if you don't want your kid watching YouTube (the admin can also enable \"restricted mode\" for YouTube, which limits some mature content)."
    },
    {
      "ref": "[D512]",
      "area": "developer_record",
      "claim": "A parent reports that the developer has not been fined, breached, sued, or subject to regulatory actions regarding children's data.",
      "stance": "neutral",
      "quote": "Google doesn't share or sell student data to partners, and it vets the developers it uses for Classroom."
    }
  ]
}
